fn copy<T: Copy>(a: &Vec<T>) -> Vec<T> {
    // Pre-allocate a new vector with the same length as `a`.
    let mut result = Vec::with_capacity(a.len());
    // Iterate over `a` by reference, copy each element, and push into `result`.
    for &item in a.iter() {
        result.push(item);
    }
    result
}

